	/** Item id for its icon, resolved from the client's item list. */
	private int itemId(String name)
	{
		for (final ItemPrice ip : itemManager.search(name))
		{
			if (ip.getName().equalsIgnoreCase(name))
			{
				return ip.getId();
			}
		}
